{
  "items": [
    {
      "name": "MvPowerSeries.weightedOrder_le",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] (w : σ → ℕ) {f : MvPowerSeries σ R} {d : σ →₀ ℕ},\n  (MvPowerSeries.coeff d) f ≠ 0 → MvPowerSeries.weightedOrder w f ≤ ↑((Finsupp.weight w) d)"
    },
    {
      "name": "MvPowerSeries.weightedOrder",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "definition",
      "type": "{σ : Type u_1} → {R : Type u_2} → [Semiring R] → (σ → ℕ) → MvPowerSeries σ R → ℕ∞"
    },
    {
      "name": "PowerSeries.le_weightedOrder_subst",
      "module_name": "Mathlib.RingTheory.PowerSeries.Substitution",
      "kind": "theorem",
      "type": "∀ {R : Type u_2} [inst : CommRing R] {τ : Type u_3} {S : Type u_4} [inst_1 : CommRing S] [inst_2 : Algebra R S]\n  {a : MvPowerSeries τ S} (w : τ → ℕ),\n  PowerSeries.HasSubst a →\n    ∀ (f : PowerSeries R),\n      f.order * MvPowerSeries.weightedOrder w a ≤ MvPowerSeries.weightedOrder w (PowerSeries.subst a f)"
    },
    {
      "name": "analyticOrderAt_add_eq_right_of_lt",
      "module_name": "Mathlib.Analysis.Analytic.Order",
      "kind": "theorem",
      "type": "∀ {𝕜 : Type u_1} {E : Type u_2} [inst : NontriviallyNormedField 𝕜] [inst_1 : NormedAddCommGroup E]\n  [inst_2 : NormedSpace 𝕜 E] {f g : 𝕜 → E} {z₀ : 𝕜},\n  analyticOrderAt g z₀ < analyticOrderAt f z₀ → analyticOrderAt (f + g) z₀ = analyticOrderAt g z₀"
    },
    {
      "name": "MvPowerSeries.nat_le_weightedOrder",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] (w : σ → ℕ) {f : MvPowerSeries σ R} {n : ℕ},\n  (∀ (d : σ →₀ ℕ), (Finsupp.weight w) d < n → (MvPowerSeries.coeff d) f = 0) → ↑n ≤ MvPowerSeries.weightedOrder w f"
    },
    {
      "name": "MvPowerSeries.le_weightedOrder_map",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] (w : σ → ℕ) {f : MvPowerSeries σ R} {S : Type u_3}\n  [inst_1 : Semiring S] (φ : R →+* S),\n  MvPowerSeries.weightedOrder w f ≤ MvPowerSeries.weightedOrder w ((MvPowerSeries.map φ) f)"
    }
  ]
}

